fixture_files.tests/test_shipping.py:
from __future__ import annotations

import subprocess
import sys


def run(total: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run([sys.executable, "shipping.py", total], text=True, capture_output=True, check=False)


def test_below_threshold_costs_ten() -> None:
    result = run("99.99")
    assert result.returncode == 0
    assert result.stdout == "10\n"


def test_above_threshold_is_free() -> None:
    result = run("100.01")
    assert result.returncode == 0
    assert result.stdout == "0\n"

